const long long MOD=1e9+7;
int main(){int t;scanf("%d",&t);while(t--){int n;scanf("%d",&n);vector<vector<int>>g(n+1);
 for(int i=0;i<n-1;i++){int u,v;scanf("%d %d",&u,&v);g[u].push_back(v);g[v].push_back(u);}
 int m;scanf("%d",&m);vector<long long>p(m);for(auto&x:p)scanf("%lld",&x);sort(p.rbegin(),p.rend());
 vector<int>par(n+1,0),ord,st={1};par[1]=-1;vector<long long>sz(n+1,1),c;
 while(!st.empty()){int v=st.back();st.pop_back();ord.push_back(v);for(int u:g[v])if(u!=par[v]){par[u]=v;st.push_back(u);}}
 for(int i=n-1;i>0;i--){int v=ord[i];sz[par[v]]+=sz[v];c.push_back(sz[v]*(n-sz[v]));}
 sort(c.rbegin(),c.rend());vector<long long>lab(n-1,1);
 if(m>n-1){long long pr=1;int extra=m-(n-1);for(int i=0;i<=extra;i++)pr=pr*p[i]%MOD;lab[0]=pr;for(int i=1;i<n-1;i++)lab[i]=p[i+extra];}
 else for(int i=0;i<m;i++)lab[i]=p[i];
 long long ans=0;for(int i=0;i<n-1;i++)ans=(ans+c[i]%MOD*lab[i])%MOD;printf("%lld\n",ans);}}

