int main(){int W,B;cin>>W>>B;
 for(int w=0;w<=W;w++)for(int b=0;b<=B;b++){
  if(w==0){dp[w][b]=0;continue;}if(b==0){dp[w][b]=1;continue;}
  double t=w+b,r=(double)w/t;
  if(b>=2){double base=(double)b/t*(b-1)/(t-1),x=0;
   if(t-2>0){x+=(double)w/(t-2)*dp[w-1][b-2];if(b>=3)x+=(double)(b-2)/(t-2)*dp[w][b-3];}
